  switch  ( isLeap )   { 
    case 0:  { 
       ( *temptemp1 )  =  ( *yr )  ; 
       ; 
     }  break ; 
    case 1:  { 
       ( *temptemp2 )  =  ( *yr )  ; 
       ; 
     }  break ; 
   }  ; 
  return 0 ; 
 }

