     { 
       ( *temptemp2 )  = j + 1 ; 
       ( *temptemp3 )  = values [ j ]  ; 
       ; 
     } 
    j++ ; 
   } 
   { 
     ( *temptemp4 )  = total ; 
     ; 
   } 
  return 0 ; 
 }

