   ; 
  factorial = 1 ; 
  i =  ( *n )  ; 
  while  ( i >= 1 )   { 
    factorial = factorial * i ; 
    i-- ; 
   } 
   { 
     ( *temptemp1 )  =  ( *n )  ; 
     ( *temptemp2 )  = factorial ; 
     ; 
   } 
  return 0 ; 
 }

