    j = 0 ; 
    while  ( j <=  ( cnt / 2 )  )   { 
       { 
         ( *temptemp1 )  = sym++ ; 
         ; 
       } 
      j++ ; 
     } 
    sym = sym - 2 ; 
    j = 0 ; 
    while  ( j <  ( cnt / 2 )  )   { 
       { 
         ( *temptemp2 )  = sym-- ; 
         ; 
       } 
      j++ ; 
     } 
    cnt = cnt + 2 ; 
    sym = 'A' ; 
     ; 
    i++ ; 
   } 
  return  ( 0 )  ; 
  return 0 ; 
 }

