  product = 0 ; 
  counter = 1 ; 
  while  ( counter <=  ( *num2 )  )   { 
    product +=  ( *num1 )  ; 
    counter++ ; 
   } 
   { 
     ( *temptemp1 )  =  ( *num1 )  ; 
     ( *temptemp2 )  =  ( *num2 )  ; 
     ( *temptemp3 )  = product ; 
     ; 
   } 
  return 0 ; 
 }

